const D = { rings:5, sym:8, density:.55, scale:1, speed:1, energy:.6, hue:32, x:.5, y:.5, style:'sand', act:'cycle', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const W=width, H=height, u=Math.min(W,H), TAU=Math.PI*2;
const clp=(v,a,b)=>Math.max(a,Math.min(b,v));
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};
if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat; S.lastBeat=K.beat;
const st=P.style, intn=(K.intensity!=null?K.intensity:.6);
const rings=Math.round(clp(P.rings,3,9));
const sym=Math.round(clp(P.sym,4,24));

// ---- per-style palette + ground tone ----
function theme(s,baseH){
  const H0=((baseH%360)+360)%360;
  const ring=k=>[ (H0 + k*37)%360, 62, 92 ];
  if(s==='ink')      return {bg:[38,10,90], line:[28,18,14], fill:null, dot:[26,20,10], grain:false, glow:false, cols:[[28,18,16]] };
  if(s==='stained')  return {bg:[224,30,10], line:[224,20,6], fill:1, dot:null, grain:false, glow:false, cols:[[H0,80,70],[(H0+120)%360,78,66],[(H0+210)%360,72,74],[(H0+300)%360,80,64],[(H0+60)%360,84,76]] };
  if(s==='neon')     return {bg:[262,60,6], line:null, fill:null, dot:null, grain:false, glow:true, cols:[[H0,90,100],[(H0+90)%360,90,100],[(H0+180)%360,90,100],[(H0+270)%360,90,100]] };
  if(s==='blueprint')return {bg:[220,74,9], line:[196,64,90], fill:null, dot:null, grain:false, glow:false, cols:[[196,60,88]] };
  return {bg:[30,32,30], line:[24,30,20], fill:1, dot:1, grain:true, cols:[[H0,70,88],[(H0+150)%360,60,84],[(H0+40)%360,78,90],[(H0+220)%360,66,80],[(H0+90)%360,72,86],[(H0+300)%360,68,82]] };
}
const T=theme(st,P.hue);
const col=k=>T.cols[((k%T.cols.length)+T.cols.length)%T.cols.length];

// ---- baked mandala buffer (rebuilt on structure/seed/style change) ----
const Bs=Math.max(64,Math.ceil(u*0.98));
const Rb=Bs*0.47;
const bkey=Bs+'|'+rings+'|'+sym+'|'+st+'|'+P.seed+'|'+Math.round(P.hue/4)+'|'+Math.round(P.density*10);
if(!S.buf || S.bkey!==bkey){
  S.bkey=bkey;
  const g=createGraphics(Bs,Bs); g.colorMode(HSB,360,100,100,100);
  g.push(); g.translate(Bs/2,Bs/2);
  const grainOn=T.grain && P.density>0.05;
  // central bindu
  const c0=col(0);
  g.noStroke(); g.fill(c0[0],c0[1],c0[2],95); g.circle(0,0,Rb*0.10);
  if(T.line){ g.noFill(); g.stroke(T.line[0],T.line[1],T.line[2],80); g.strokeWeight(Math.max(1,Rb*0.006)); g.circle(0,0,Rb*0.12); }
  for(let r=0;r<rings;r++){
    const rr=Rb*(0.16 + (r+1)/rings*0.82);
    const rin=Rb*(0.16 + (r)/rings*0.82);
    const mt=Math.floor(fr(r*3.7+1)*4);        // motif type per ring (seeded)
    const cc=col(r+1);
    const cnt = mt===1 ? sym*2 : sym;
    // concentric guide circle
    if(T.line){ g.noFill(); g.stroke(T.line[0],T.line[1],T.line[2],55); g.strokeWeight(Math.max(0.8,Rb*0.004)); g.circle(0,0,rr*2); }
    if(st==='blueprint'){
      // schematic: radii + chord polygon + tick arcs (construction diagram)
      g.stroke(T.line[0],T.line[1],T.line[2],48); g.strokeWeight(1);
      g.beginShape(); g.noFill();
      for(let i=0;i<sym;i++){ const a=i/sym*TAU; g.vertex(Math.cos(a)*rr,Math.sin(a)*rr); }
      g.endShape(CLOSE);
      for(let i=0;i<sym;i++){ const a=i/sym*TAU; g.line(0,0,Math.cos(a)*rr,Math.sin(a)*rr); }
      continue;
    }
    for(let i=0;i<cnt;i++){
      const a=i/cnt*TAU;
      g.push(); g.rotate(a); g.translate(0,-(rin+rr)/2);
      const petL=(rr-rin)*0.92, petW=(rr-rin)*0.5*(0.7+fr(r*5.1)*0.6);
      if(mt===0){ // petal / lotus
        if(T.fill){ g.noStroke(); g.fill(cc[0],cc[1],cc[2],90); }
        else { g.noFill(); g.stroke(T.line?T.line[0]:cc[0],T.line?T.line[1]:cc[1],T.line?T.line[2]:cc[2],85); g.strokeWeight(Math.max(1,Rb*0.006)); }
        g.beginShape();
        g.vertex(0,-petL*0.5);
        g.bezierVertex(petW,-petL*0.15, petW*0.6,petL*0.4, 0,petL*0.5);
        g.bezierVertex(-petW*0.6,petL*0.4, -petW,-petL*0.15, 0,-petL*0.5);
        g.endShape(CLOSE);
        if(st==='stained'){ g.noFill(); g.stroke(T.line[0],T.line[1],T.line[2],95); g.strokeWeight(Math.max(1.4,Rb*0.008)); g.beginShape(); g.vertex(0,-petL*0.5); g.bezierVertex(petW,-petL*0.15, petW*0.6,petL*0.4, 0,petL*0.5); g.bezierVertex(-petW*0.6,petL*0.4, -petW,-petL*0.15, 0,-petL*0.5); g.endShape(CLOSE); }
      } else if(mt===1){ // dot
        if(T.fill||T.dot){ g.noStroke(); g.fill(cc[0],cc[1],cc[2],92); }
        else { g.noFill(); g.stroke(cc[0],cc[1],cc[2],88); g.strokeWeight(Math.max(1,Rb*0.006)); }
        g.circle(0,0,petL*0.5);
      } else if(mt===2){ // triangle
        if(T.fill){ g.noStroke(); g.fill(cc[0],cc[1],cc[2],88); }
        else { g.noFill(); g.stroke(cc[0],cc[1],cc[2],86); g.strokeWeight(Math.max(1,Rb*0.006)); }
        g.triangle(0,-petL*0.5, petW*0.8,petL*0.45, -petW*0.8,petL*0.45);
      } else { // scallop arc
        g.noFill(); g.stroke(cc[0],cc[1],cc[2],85); g.strokeWeight(Math.max(1.2,Rb*0.009));
        g.arc(0,petL*0.2, petW*1.6, petL*0.9, Math.PI*1.15, Math.PI*1.85);
      }
      // sand grain stipple
      if(grainOn){
        g.noStroke();
        const ng=Math.round(4+P.density*10);
        for(let d2=0;d2<ng;d2++){
          const gx=(fr(r*13+i*2.1+d2*0.7)-0.5)*petW*1.2;
          const gy=(fr(r*7+i*3.3+d2*1.9)-0.5)*petL*0.9;
          const gb=cc[2]*(0.6+fr(d2*4.4)*0.6);
          g.fill(cc[0], cc[1]*(0.5+fr(d2)*0.5), Math.min(100,gb), 55);
          g.circle(gx,gy, Rb*0.006+0.5);
        }
      }
      g.pop();
    }
  }
  g.pop();
  S.buf=g;
}

// ---- dramaturgy: reveal progress + dissolve ----
let prog=1, dis=0;
if(P.act==='steady'){ prog=1; dis=0; }
else if(P.act==='build'){ prog=clp(K.t/18,0,1); dis=0; }
else { // cycle: build -> hold -> wind-dissolve -> loop
  const per=44/(0.4+P.speed*0.6);
  const ph=((K.t/per)%1+1)%1;
  if(ph<0.42) prog=ph/0.42;
  else if(ph<0.72){ prog=1; dis=0; }
  else { prog=1; dis=(ph-0.72)/0.28; }
}
prog=clp(prog+ A.rms*0.1,0,1);

// ---- background ----
noStroke();
const bg=T.bg;
for(let yy=0; yy<H; yy+=Math.max(2,H/60)){ // cheap vertical vignette gradient
  const t=Math.abs(yy/H-0.5)*2;
  fill(bg[0],bg[1],bg[2]*(1-t*0.35));
  rect(0,yy,W,Math.max(2,H/60)+1);
}

// ---- draw mandala: rotate slowly, reveal via pie clip, dissolve via tint ----
const cx=clp(P.x,0,1)*W, cy=clp(P.y,0,1)*H;
const rot=K.t*0.04*P.speed + K.swell*0.02;
const sc=P.scale*(1 + K.swell*0.02*P.energy + A.bass*0.03);
push();
translate(cx,cy); rotate(rot);
imageMode(CENTER);
if(T.glow){ blendMode(ADD); }
const alpha=(1-dis)*100;
tint(0,0,100,alpha);
if(prog<0.999){
  drawingContext.save();
  drawingContext.beginPath();
  drawingContext.moveTo(0,0);
  drawingContext.arc(0,0, Rb*sc*1.1, -Math.PI/2, -Math.PI/2 + prog*TAU);
  drawingContext.closePath();
  drawingContext.clip();
  image(S.buf,0,0,Bs*sc,Bs*sc);
  drawingContext.restore();
} else {
  image(S.buf,0,0,Bs*sc,Bs*sc);
}
noTint();
imageMode(CORNER);
blendMode(BLEND);

// growing-edge sparkle at the construction front
if(prog<1 && st!=='blueprint'){
  const ea=-Math.PI/2 + prog*TAU;
  noStroke();
  for(let s2=0;s2<10;s2++){
    const rr=Rb*sc*(0.2+fr(s2*2.2)*0.85);
    const jx=Math.cos(ea)*rr + (fr(s2*4+K.t)-0.5)*u*0.02;
    const jy=Math.sin(ea)*rr + (fr(s2*9+K.t*1.3)-0.5)*u*0.02;
    const cc=col(s2);
    fill(cc[0],cc[1],100, 70+30*Math.sin(K.t*3+s2));
    circle(jx,jy, u*0.006+1.5);
  }
}
pop();

// ---- shimmer sweep: rotating highlight (non-symmetric => motion floor) ----
push();
translate(cx,cy);
blendMode(ADD);
const swAng=K.t*(0.5+P.speed*0.4);
for(let b=0;b<3;b++){
  const a=swAng + b*TAU/3;
  const rr=Rb*sc*0.9;
  const hx=Math.cos(a)*rr*0.6, hy=Math.sin(a)*rr*0.6;
  const cc=col(b+1);
  noStroke(); fill(cc[0], cc[1]*0.4, 100, 6+4*Math.sin(K.t*1.3+b) + A.treble*20);
  ellipse(hx,hy, rr*0.7, rr*0.7);
}
// central breathing bindu on the beat
const c0=col(0);
fill(c0[0],c0[1]*0.5,100, 20+K.pulse*40 + A.bass*30);
circle(0,0, Rb*sc*(0.14+K.swell*0.05));
blendMode(BLEND);
pop();

// ---- wind-blown sand during dissolve (seeded particles drift +x) ----
if(dis>0.01){
  noStroke();
  const nP=Math.round(140*dis);
  for(let i=0;i<nP;i++){
    const a=fr(i*1.3)*TAU, rr=Rb*sc*fr(i*2.7);
    const life=dis;
    const wind=life*life*u*0.5*(0.6+P.speed*0.6);
    const bx=cx+Math.cos(a+rot)*rr + wind + Math.sin(K.t*2+i)*u*0.01;
    const by=cy+Math.sin(a+rot)*rr + (fr(i*5.5)-0.5)*u*0.04 + Math.sin(K.t*1.5+i*0.3)*u*0.02;
    const cc=col(i%6);
    fill(cc[0],cc[1],cc[2], (1-life)*70+10);
    circle(bx,by, u*0.004+1);
  }
}

blendMode(BLEND);
drawingContext.shadowBlur=0;
